content:
:root {
  --bg-primary: #0f172a;
  --panel-bg: rgba(15, 23, 42, 0.85);
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-label: #cbd5e1;
  --border-color: rgba(255, 255, 255, 0.1);
  --border-btn: #334155;
  --accent-primary: #38bdf8;
  --accent-active: #3b82f6;
  --accent-active-hover: #2563eb;
  --slider-bg: #334155;
  --btn-bg: #1e293b;
  --btn-hover: #334155;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  overflow: hidden;
  height: 100vh;
  width: 100vw;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  overflow: hidden;
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.particle-canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.controls-panel {
  position: relative;
  z-index: 10;
  background: var(--panel-bg);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 20px 24px;
  margin-bottom: 24px;
  width: 90%;
  max-width: 500px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.title {
  font-size: 1.25rem;
  font-weight: 700;
  text-align: center;
  background: linear-gradient(135deg, #60a5fa, #a855f7, #ec4899);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 4px;
}

.info-text {
  font-size: 0.85rem;
  text-align: center;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.control-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-label);
  display: flex;
  justify-content: space-between;
}

.slider {
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: var(--slider-bg);
  outline: none;
  -webkit-appearance: none;
}

.slider:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--accent-primary);
}

.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-primary);
  cursor: pointer;
  transition: transform 0.1s ease;
}

.slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.btn-group {
  display: flex;
  gap: 8px;
  justify-content: space-between;
}

.btn {
  flex: 1;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--border-btn);
  background: var(--btn-bg);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  background: var(--btn-hover);
  color: var(--text-primary);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--accent-primary);
}

.btn-active {
  background: var(--accent-active);
  border-color: #60a5fa;
  color: #ffffff;
  box-shadow: 0 0 10px rgba(59, 130, 246, 0.5);
}

.btn-active:hover {
  background: var(--accent-active-hover);
}

@media (max-width: 640px) {
  .controls-panel {
    padding: 16px;
    width: 95%;
    margin-bottom: 16px;
  }
}

/**
 * パーティクルのカラーテーマの定義
 */
export const COLOR_THEMES = ['rainbow', 'neon', 'gold'] as const;
export type ColorTheme = typeof COLOR_THEMES[number];

/**
 * パーティクルアニメーションの設定
 */
export interface ParticleSettings {
  /** パーティクル数 (推奨範囲: 30 - 300) */
  count: number;
  /** カラーテーマ */
  colorTheme: ColorTheme;
  /** 移動速度 (推奨範囲: 0.2 - 3.0) */
  speed: number;
  /** パーティクルサイズ (推奨範囲: 2 - 10) */
  particleSize: number;
}

import { useState } from 'react';
import { ParticleSettings } from './types';
import { useParticleCanvas } from './hooks/useParticleCanvas';
import ControlsPanel from './components/ControlsPanel';
import './index.css';

export default function App() {
  const [settings, setSettings] = useState<ParticleSettings>({
    count: 120,
    colorTheme: 'neon',
    speed: 1.0,
    particleSize: 4,
  });

  const { canvasRef } = useParticleCanvas(settings);

  return (
    <div className="app-container">
      <div className="canvas-container">
        <canvas ref={canvasRef} className="particle-canvas" />
      </div>

      <ControlsPanel settings={settings} onSettingsChange={setSettings} />
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { ParticleSettings, ColorTheme } from '../types';

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  angle: number;
  speed: number;
}

const getColor = (theme: ColorTheme, index: number, total: number) => {
  if (theme === 'rainbow') {
    const hue = (index / total) * 360;
    return `hsl(${hue}, 100%, 60%)`;
  } else if (theme === 'neon') {
    const colors = ['#38bdf8', '#818cf8', '#c084fc', '#f472b6', '#34d399'];
    return colors[index % colors.length];
  } else {
    const colors = ['#fbbf24', '#f59e0b', '#d97706', '#fef3c7', '#b45309'];
    return colors[index % colors.length];
  }
};

export function useParticleCanvas(settings: ParticleSettings) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const mouseRef = useRef<{ x: number; y: number; active: boolean }>({
    x: window.innerWidth / 2,
    y: window.innerHeight / 2,
    active: false,
  });
  const particlesRef = useRef<Particle[]>([]);

  useEffect(() => {
    const width = window.innerWidth;
    const height = window.innerHeight;
    const newParticles: Particle[] = [];

    for (let i = 0; i < settings.count; i++) {
      newParticles.push({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: (Math.random() - 0.5) * 2,
        vy: (Math.random() - 0.5) * 2,
        size: settings.particleSize * (0.5 + Math.random() * 0.5),
        color: getColor(settings.colorTheme, i, settings.count),
        angle: Math.random() * Math.PI * 2,
        speed: 0.5 + Math.random() * 1.5,
      });
    }
    particlesRef.current = newParticles;
  }, [settings.count, settings.colorTheme, settings.particleSize]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      mouseRef.current = { x: e.clientX, y: e.clientY, active: true };
    };

    const handleMouseLeave = () => {
      mouseRef.current.active = false;
      mouseRef.current.x = window.innerWidth / 2;
      mouseRef.current.y = window.innerHeight / 2;
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        mouseRef.current = { x: e.touches[0].clientX, y: e.touches[0].clientY, active: true };
      }
    };

    const handleTouchEnd = () => {
      mouseRef.current.active = false;
    };

    const handleResize = () => {
      if (canvasRef.current) {
        const oldWidth = canvasRef.current.width;
        const oldHeight = canvasRef.current.height;
        const newWidth = window.innerWidth;
        const newHeight = window.innerHeight;

        canvasRef.current.width = newWidth;
        canvasRef.current.height = newHeight;

        particlesRef.current.forEach((p) => {
          if (oldWidth > 0 && oldHeight > 0) {
            p.x = (p.x / oldWidth) * newWidth;
            p.y = (p.y / oldHeight) * newHeight;
          }
          if (p.x < 0) p.x = 0;
          if (p.x > newWidth) p.x = newWidth;
          if (p.y < 0) p.y = 0;
          if (p.y > newHeight) p.y = newHeight;
        });
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseleave', handleMouseLeave);
    window.addEventListener('touchmove', handleTouchMove);
    window.addEventListener('touchend', handleTouchEnd);
    window.addEventListener('resize', handleResize);

    if (canvasRef.current) {
      canvasRef.current.width = window.innerWidth;
      canvasRef.current.height = window.innerHeight;
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseleave', handleMouseLeave);
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  useEffect(() => {
    let animationFrameId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const render = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const mouse = mouseRef.current;
      const particles = particlesRef.current;

      particles.forEach((p) => {
        const targetX = mouse.x;
        const targetY = mouse.y;

        const dx = targetX - p.x;
        const dy = targetY - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (mouse.active && dist > 1) {
          const force = (120 / (dist + 120)) * settings.speed;
          p.vx += (dx / dist) * force * 0.25;
          p.vy += (dy / dist) * force * 0.25;
        } else {
          p.vx += (Math.random() - 0.5) * 0.2;
          p.vy += (Math.random() - 0.5) * 0.2;
        }

        p.vx *= 0.92;
        p.vy *= 0.92;

        p.x += p.vx * settings.speed;
        p.y += p.vy * settings.speed;

        if (p.x < 0) p.x = canvas.width;
        if (p.x > canvas.width) p.x = 0;
        if (p.y < 0) p.y = canvas.height;
        if (p.y > canvas.height) p.y = 0;

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.shadowBlur = 12;
        ctx.shadowColor = p.color;
        ctx.fill();
        ctx.closePath();
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [settings.speed]);

  return { canvasRef };
}
